    for _, a, b in savings:
        ia = cust_route.get(a)
        ib = cust_route.get(b)
        if ia is None or ib is None or ia == ib or not active[ia] or not active[ib]:
            continue
        ra, rb = routes[ia], routes[ib]
        if route_load(ra) + route_load(rb) > capacity:
            continue
        nr = None
        if ra[-1] == a and rb[0] == b:
            nr = ra + rb
        elif ra[0] == a and rb[-1] == b:
            nr = rb + ra
        elif ra[0] == a and rb[0] == b:
            nr = ra[::-1] + rb
        elif ra[-1] == a and rb[-1] == b:
            nr = ra + rb[::-1]
        if nr is not None:
            routes[ia] = nr
            active[ib] = False
            for c in nr:
                cust_route[c] = ia
    routes = [r for i, r in enumerate(routes) if active[i] and r]

    for i in range(len(routes)):
        routes[i] = two_opt(routes[i])

    changed = True
    while changed:
        changed = False
        base = sum(route_cost(r) for r in routes)
        best = None
        best_delta = 0.0
        for i in range(len(routes)):
            ri = routes[i]
            for p in range(len(ri)):
                c = ri[p]
                dc = demand_of(c)
                rem = ri[:p] + ri[p + 1:]
                if not rem:
                    continue
                for j in range(len(routes)):
                    if i == j:
                        continue
                    rj = routes[j]
                    if route_load(rj) + dc > capacity:
                        continue
                    for ins in range(len(rj) + 1):
                        nrj = rj[:ins] + [c] + rj[ins:]
                        cand = []
                        for k in range(len(routes)):
                            if k == i:
                                cand.append(rem)
                            elif k == j:
                                cand.append(nrj)
                            else:
                                cand.append(routes[k][:])
                        cand = [two_opt(r) for r in cand if r]
                        cc = sum(route_cost(r) for r in cand)
                        if cc + 1e-12 < base + best_delta:
                            best = cand
                            best_delta = cc - base
        if best is not None:
            routes = best
            changed = True

    present = {}
    for r in routes:
        for c in r:
            present[c] = present.get(c, 0) + 1

    unique = []
    seen = {}
    for r in routes:
        nr = []
        for c in r:
            if seen.get(c, 0) == 0:
                seen[c] = 1
                nr.append(c)
        if nr:
            unique.append(nr)
    routes = unique

    missing = [c for c in customers if seen.get(c, 0) == 0]
    for c in missing:
        dc = demand_of(c)
        best_i, best_ins, best_delta = None, None, None
        for i in range(len(routes)):
            if route_load(routes[i]) + dc > capacity:
                continue
            r = routes[i]
            rc = route_cost(r)
            for ins in range(len(r) + 1):
                cand = r[:ins] + [c] + r[ins:]
                dlt = route_cost(cand) - rc
                if best_delta is None or dlt < best_delta or (dlt == best_delta and (i, ins) < (best_i, best_ins)):
                    best_i, best_ins, best_delta = i, ins, dlt
        if best_i is None:
            routes.append([c])
        else:
            routes[best_i] = two_opt(routes[best_i][:best_ins] + [c] + routes[best_i][best_ins:])

    final = []
    for r in routes:
        buf = []
        load = 0.0
        for c in r:
            d = demand_of(c)
            if buf and load + d > capacity:
                final.append(two_opt(buf))
                buf = [c]
                load = d
            else:
                buf.append(c)
                load += d
        if buf:
            final.append(two_opt(buf))

    return final
